def test_search_until_returns_partial_results_on_timeout() -> None:
    exporter = InMemoryLogExporter()
    target = LoggingTarget(
        client=BatchingLogClient(exporter), query=InMemoryLogQueryClient(exporter)
    )
    ctx = StepContext({}, target, {})
    logging_ops["send"](ctx, {"message": "only one", "severity": "WARN"})
    ctx.resolve(logging_ops["flush"](ctx, {}))
    found = ctx.resolve(
        logging_ops["searchUntil"](
            ctx, {"query": "only", "minCount": 2, "timeoutMs": 50, "intervalMs": 10}
        )
    )
    assert [r.body for r in found] == ["only one"]
    ctx.close()
    target.client.close()


def test_send_batch_indexes_nested_values() -> None:
    exporter = InMemoryLogExporter()
    target = LoggingTarget(client=BatchingLogClient(exporter))
    ctx = StepContext({}, target, {})
    logging_ops["sendBatch"](
        ctx, {"count": 2, "message": "m#{i}", "attributes": {"i": "#{i}", "l": ["#{i}", 3]}}
    )
    target.client.flush(5)
    assert [dict(r.attributes) for r in exporter.records] == [
        {"i": "0", "l": ["0", 3]},
        {"i": "1", "l": ["1", 3]},
    ]
    target.client.close()
